// Verdant site — generated by Panda. The scripts in this folder are the only
// "source" Panda extracts from (see panda.config.ts `include`): every
// css()/pattern()/recipe() call is a literal call, so `panda cssgen` can
// statically find it and emit exactly the CSS the pages use, nothing more.
import { writeFileSync, mkdirSync, readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
